// Matches a line that consists solely of a DSPy section marker `[[ ## name ## ]]`,
// optionally surrounded by leading/trailing whitespace. Markers embedded within other
// text (e.g. inside a backtick inline code span) will not match and are left untouched.
const DSPY_SECTION_MARKER_REGEX = /^\s*\[\[\s*##\s*(\w+)\s*##\s*\]\]\s*$/;

// Title-cases a snake_case marker name, e.g. `tool_name_0` -> `Tool Name 0`.
const titleCaseMarkerName = (name: string): string =>
  name
    .split('_')
    .map((word) => (word.length > 0 ? word.charAt(0).toUpperCase() + word.slice(1) : word))
    .join(' ');

// Converts standalone DSPy section markers (`[[ ## name ## ]]` on their own line) into
// markdown level-4 headings (`#### Name`). The `completed` marker is removed entirely,
// and markers appearing inside backtick inline code spans are left unchanged.
export const formatDspySections = (input: string): string => {
  if (!input) {
    return input;
  }

  return input
    .split('\n')
    .map((line) => {
      const match = line.match(DSPY_SECTION_MARKER_REGEX);
      if (!match) {
        return line;
      }

      const name = match[1];
      if (name === 'completed') {
        return '';
      }

      return `#### ${titleCaseMarkerName(name)}`;
    })
    .join('\n');
};

// Attempts to parse a string as a JSON object or array, returning undefined if the
// string is not valid JSON or does not represent an object/array.
const tryParseJsonObject = (text: string): unknown | undefined => {
  try {
    const parsed = JSON.parse(text);
    if (parsed !== null && typeof parsed === 'object') {
      return parsed;
    }
  } catch {
    // not valid JSON
  }

  return undefined;
