r, l: number): number[] {\n  h /= 60, s /= 100, l /= 100;\n  const c = (1 - Math.abs(2 * l - 1)) * s;\n  const x = c * (1 - Math.abs(h % 2 - 1));\n  const m = l - c / 2;\n  let r;\n  let g;\n  let b;\n  switch (Math.floor(h)) {\n    case 0: r = c, g = x, b = 0; break;\n    case 1: r = x, g = c, b = 0; break;\n    case 2: r = 0, g = c, b = x; break;\n    case 3: r = 0, g = x, b = c; break;\n    case 4: r = x, g = 0, b = c; break;\n    case 5: r = c, g = 0, b = x; break;\n  }\n  return [r, g, b].map(val => (val + m) * 255);\n}\n\n/**\n * Converts RGB to HSL.\n * @see https://www.rapidtables.com/convert/color/rgb-to-hsl.html\n * @export\n * @param {number} r red 0-255\n * @param {number} g green 0-255\n * @param {number} b blue 0-255\n * @returns {number[]} [hue, saturation, lightness] (0-360, 0-100, 0-100)\n */\nexport function rgbToHsl(r: number, g: number, b: number): number[] {\n  r /= 255, g /= 255, b /= 255;\n  const max = Math.max(r, g, b);\n  const min = Math.min(r, g, b);\n  const delta = max - min;\n  let h;\n  let s;\n  let l;\n  if (delta === 0) {\n    h = 0;\n  } else if (max === r) {\n    h = 60 * ((g - b) / delta % 6);\n  } else if (max === g) {\n    h = 60 * ((b - r) / delta + 2);\n  } else {\n    h = 60 * ((r - g) / delta + 4);\n  }\n  l = (max + min) / 2;\n  s = delta === 0 ? 0 : delta / (1 - Math.abs(2 * l - 1));\n  return [h, s * 100, l * 100];\n}\n\n/**\n * Converts HWB to RGB.\n * @export\n * @param {number} hue hue 0-360\n * @param {number} white whiteness 0-100\n * @param {number} black blackness 0-100\n * @returns {number[]} [red, green, blue] 0-255\n */\nexport function hwbToRgb(hue: number, white: number, black: number): number[] {\n  const [h, s, v] = hwbToHsv(hue, white, black);\n  return hsvToRgb(h, s, v);\n}\n\n/**\n * Converts RGB to HWB.\n * @export\n * @param {number} r red 0-255\n * @param {number} g green 0-255\n * @param {number} b blue 0-255\n * @returns {number[]} [hue, whiteness, blackness] (0-360, 0-100, 0-100)\n */\nexport function rgbToHwb(r: number, g: number, b: number): number[] {\n  const [h, s, v] = rgbToHsv(r, g, b);\n  return hsvToHwb(h, s, v);\n}\n\n/**\n * Converts CMYK to RGB.\n * @see https://www.rapidtables.com/convert/color/cmyk-to-rgb.html\n * @export\n * @param {number} c cyan 0-100\n * @param {number} m magenta 0-100\n * @param {number} y yellow 0-100\n * @param {number} k black 0-100\n * @returns {number[]} [red, green, blue] 0-255\n */\nexport function cmykToRgb(c: number, m: number, y: number, k: number): number[] {\n  c /= 100, m /= 100, y /= 100, k /= 100;\n  const red = 255 * (1 - c) * (1 - k);\n  const green = 255 * (1 - m) * (1 - k);\n  const blue = 255 * (1 - y) * (1 - k);\n  return [red, green, blue];\n}\n\n/**\n * Converts RGB to CMYK\n * @see https://www.rapidtables.com/convert/color/rgb-to-cmyk.html\n * @export\n * @param {number} r red 0-255\n * @param {number} g green 0-255\n * @param {number} b blue 0-255\n * @returns {number[]} [cyan, magenta, yellow, black] 0-100\n */\nexport function rgbToCmyk(r: number, g: number, b: number): number[] {\n  r /= 255, g /= 255, b /= 255;\n  const k = 1 - Math.max(r, g, b);\n  const c = (1 - r - k) / (1 - k);\n  const m = (1 - g - k) / (1 - k);\n  const y = (1 - b - k) / (1 - k);\n  return [c, m, y, k].map(x => x * 100);\n}\n\n/**\n * Converts HSV to RGB.\n * @see https://www.rapidtables.com/convert/color/hsv-to-rgb.html\n * @export\n * @param {number} h hue 0-360\n * @param {number} s saturation 0-100\n * @param {number} v value 0-100\n * @returns {number[]} [red, green, blue] 0-255\n */\nexport function hsvToRgb(h: number, s: number, v: number): number[] {\n  s /= 100; v /= 100;\n  let r;\n  let g;\n  let b;\n  const i = h / 60;\n  const c = v * s;\n  const x = c * (1 - Math.abs(i % 2 - 1));\n  const m = v - c;\n  switch (Math.floor(i)) {\n    case 0: r = c, g = x, b = 0; break;\n    case 1: r = x, g = c, b = 0; break;\n    case 2: r = 0, g = c, b = x; break;\n    case 3: r = 0, g = x, b = c; break;\n    case 4: r = x, g = 0, b = c; break;\n    case 5: r = c, g = 0, b = x; break;\n  }\n  return [r, g, b].map(val => (val + m) * 255);\n}\n\n/**\n * Converts RGB to HSV.\n * @see https://www.rapidtables.com/convert/color/rgb-to-hsv.html\n * @export\n * @param {number} r red 0-255\n * @param {number} g green 0-255\n * @param {number} b blue 0-255\n * @returns {number[]} [hue, saturation, value] (0-360, 0-100, 0-100)\n */\nexport function rgbToHsv(r: number, g: number, b: number): number[] {\n  r /= 255, g /= 255, b /= 255;\n  let h;\n  let s;\n  let v;\n  const max = Math.max(r, g, b);\n  const min = Math.min(r, g, b);\n  const delta = max - min;\n  if (delta === 0) {\n    h = 0;\n  } else if (max === r) {\n    h = 60 * ((g - b) / delta % 6);\n  } else if (max === g) {\n    h = 60 * ((b - r) / delta + 2);\n  } else {\n    h = 60 * ((r - g) / delta + 4);\n  }\n  s = max === 0 ? 0 : delta / max;\n  v = max;\n  return [h, s * 100, v * 100];\n}\n\n/**\n * Converts HSV to HWB\n * @see https://en.wikipedia.org/wiki/HWB_color_model\n * @export\n * @param {number} h hue 0-360\n * @param {number} s saturation 0-100\n * @param {number} v value 0-100\n * @returns {number[]} [hue, whiteness, blackness] (0-360, 0-100, 0-100)\n */\nexport function hsvToHwb(h: number, s: number, v: number): number[] {\n  s /= 100, v /= 100;\n  const white = (1 - s) * v;\n  const black = 1 - v;\n  return [h, white * 100, black * 100];\n}\n\n/**\n * Converts HWB to HSV.\n * @see https://en.wikipedia.org/wiki/HWB_color_model\n * @export\n * @param {number} h hue 0-360\n * @param {number} w whiteness 0-100\n * @param {number} b blackness 0-100\n * @returns {number[]} [hue, saturation, value] (0-360, 0-100, 0-100)\n */\nexport function hwbToHsv(h: number, w: number, b: number): number[] {\n  [h, w, b] = resolveHwb(h, w, b);\n  w /= 100, b /= 100;\n  const s = 1 - w / (1 - b);\n  const v = 1 - b;\n  return [h, s * 100, v * 100];\n}\n\n/**\n * Converts RGB to HEX string.\n * @export\n * @param {number} r red 0-255\n * @param {number} g green 0-255\n * @param {number} b blue 0-255\n * @param {(number|null)} [a] alpha 0-1 or null\n * @param {boolean} [enableShort] enable shorthand, default is false.\n * @returns {string} Hex string. e.g. 'ff0000'\n */\nexport function rgbToHex(r: number, g: number, b: number, a?: number|null, enableShort?: boolean): string {\n  const arr = [r, g, b];\n  if (typeof a === 'number') {\n    arr.push(Math.round(a * 255));\n  }\n  const hex = arr.map(x => padStart(x.toString(16), 2, '0')).join('');\n  return enableShort ? hexToShorthand(hex) : hex;\n}\n\nfunction hexToShorthand(hex: string): string {\n  let check = true;\n  const rgb = hex.match(/.{2}/g);\n  rgb.forEach(x => {\n    if (!x.match(/(.)\\1+/)) {\n      check = false;\n    }\n  });\n  return check ? rgb.map(x => x.substring(1)).join('') : hex;\n}\n\n/**\n * Converts HEX string to RGB.\n * @export\n * @param {string} hex hex string. e.g. 'ff0000', 'f00', 'ff000080'\n * @returns {number[]} [red, green, blue, alpha?] (rgb: 0-255, alpha: 0-1)\n */\nexport function hexToRgb(hex: string): number[] {\n  const short = /^#?([a-f\\d])([a-f\\d])([a-f\\d])([a-f\\d])?$/i;\n  return hex.replace(short, (m, r, g, b, a) => {\n    a = typeof a === 'undefined' ? '' : a;\n    return r + r + g + g + b + b + a + a;\n  })\n  .match(/.{2}/g)\n  .map((x, i) => i !== 3 ? parseInt(x, 16) : parseInt(x, 16) / 255);\n}\n\n/**\n * Resolve HWB values.\n * @see https://drafts.csswg.org/css-color/#the-hwb-notation\n * @export\n * @param {number} h hue 0-360\n * @param {number} w whiteness 0-100\n * @param {number} b blackness 0-100\n * @returns {number[]} [hue, whiteness, blackness]\n */\nexport function resolveHwb(h: number, w: number, b: number): number[] {\n  const total = w + b;\n  if (total > 100) {\n    w = Number((w / total).toFixed(4)) * 100;\n    b = Number((b / total).toFixed(4)) * 100;\n  }\n  return [h, w, b];\n}\n","import {\n  AcceptedModel,\n  Color,\n  ColorRepresentable,\n  ColorSettable,\n  HexMode,\n  RgbMode,\n} from './color';\nimport * as Converter from './color-converter';\nimport Names from './color-names';\nimport { arrayIsEqual, decimal, resolveAlpha } from './util/util';\n\nexport class ColorFormatter implements ColorSettable, ColorRepresentable {\n  color?: Color;\n  // In hwb model, whiteness and blackness value's adjust will required.\n  protected resolveHwb = Converter.resolveHwb;\n\n  setColor(color: Color): this {\n    color.alpha = resolveAlpha(color.alpha);\n    this.color = color;\n    return this;\n  }\n\n  getColor(): Color {\n    return this.color;\n  }\n\n  getColorAs(model: AcceptedModel): Color {\n    return this.color.model === model\n      ? this.color\n      : this.convert(this.color, model);\n  }\n\n  getModel(): AcceptedModel|undefined {\n    return this.color ? this.color.model : undefined;\n  }\n\n  changeModel(model: AcceptedModel): this {\n    return this.color.model === model\n      ? this\n      : this.setColor(this.convert(this.color, model));\n  }\n\n  getAlpha(): number {\n    return this.color.alpha;\n  }\n\n  setAlpha(alpha: number): this {\n    this.color.alpha = alpha;\n    return this;\n  }\n\n  convert(color: Color, model: AcceptedModel): Color {\n    let values: number[];\n    switch (color.model) {\n      case 'rgb': values = this.convertFromRgb(color.values, model); break;\n      case 'hwb': values = this.convertFromHwb(color.values, model); break;\n      case 'hsl': values = this.convertFromHsl(color.values, model); break;\n      case 'hsv': values = this.convertFromHsv(color.values, model); break;\n      case 'cmyk': values = this.convertFromCmyk(color.values, model); break;\n    }\n    if (!values.length) {\n      throw new Error('Converting Error!');\n    }\n    return { model, values, alpha: color.alpha};\n  }\n\n  /**\n   * Represents color as notation of specific color model.\n   *\n   * @param {(AcceptedModel|'hex')} [model] - Specify color model.\n   * If not specifying this value, then returns current color model.\n   * @param {...any[]} args - Arguments for the represent methods.\n   * @returns {string}\n   */\n  toString(model?: AcceptedModel|'hex', ...args: any[]): string {\n    model = model ? model : this.color.model;\n    switch (model) {\n      case 'hex': return this.toHex(...args);\n      case 'hwb': return this.toHwb();\n      case 'hsl': return this.toHsl();\n      case 'hsv': return this.toHsv();\n      case 'cmyk': return this.toCmyk();\n      default: return this.toRgb(...args);\n    }\n  }\n\n  /**\n   * Represents color as HEX notation.\n   * @see https://www.w3.org/TR/css-color-4/#hex-notation\n   *\n   * @param {HexMode} [mode='full'] 'full'|'short'|'name'\n   * @returns {string}\n   */\n  toHex(mode: HexMode = 'full'): string {\n    const color = this.getColorAs('rgb');\n    const [r, g, b] = color.values.map(x => Math.round(x));\n    const a = color.alpha === 1 ? null : color.alpha;\n    const nameOrShort = () => {\n      let name = '';\n      for (const key of Object.keys(Names)) {\n        if (arrayIsEqual(Names[key], [r, g, b])) {\n          name = key; break;\n        }\n      }\n      return a === null && name !== '' ? name : `#${Converter.rgbToHex(r, g, b, a, true)}`;\n    };\n    switch (mode) {\n      case 'name': return nameOrShort();\n      case 'short': return `#${Converter.rgbToHex(r, g, b, a, true)}`;\n      case 'full':\n      default: return `#${Converter.rgbToHex(r, g, b, a)}`;\n    }\n  }\n\n  /**\n   * Represents color as RGB notation.\n   * @see https://www.w3.org/TR/css-color-4/#rgb-functions\n   *\n   * @param {RgbMode} [mode='default'] 'default'|'percent'\n   * @returns {string}\n   */\n  toRgb(mode: RgbMode = 'default'): string {\n    const color = this.getColorAs('rgb');\n    let [r, g, b]: number[]|string[] = color.values.map(x => Math.round(x));\n    if (mode === 'percent') {\n      [r, g, b] = [r, g, b].map(x => `${x / 255 * 100}%`);\n    }\n    return color.alpha === 1\n      ? `rgb(${r}, ${g}, ${b})`\n      : `rgba(${r}, ${g}, ${b}, ${color.alpha})`;\n  }\n\n  /**\n   * Represents color as HWB notation.\n   * @see https://www.w3.org/TR/css-color-4/#the-hwb-notation\n   * @returns {string} e.g. 'hwb(0, 0%, 0%, 0)'\n   */\n  toHwb(): string {\n    const color = this.getColorAs('hwb');\n    const [h, w, b] = color.values.map(x => decimal(x, 2));\n    const a = color.alpha === 1 ? '' : `, ${color.alpha}`;\n    return `hwb(${h}, ${w}%, ${b}%${a})`;\n  }\n\n  /**\n   * Represents color as HSL notation.\n   * @see https://www.w3.org/TR/css-color-4/#the-hsl-notation\n   * @returns {string}\n   */\n  toHsl(): string {\n    const color = this.getColorAs('hsl');\n    const [h, s, l] = color.values.map(x => decimal(x, 2));\n    return color.alpha === 1\n      ? `hsl(${h}, ${s}%, ${l}%)`\n      : `hsla(${h}, ${s}%, ${l}%, ${color.alpha})`;\n  }\n\n  /**\n   * Represents color as HSV notation. This format is similar to HSL.\n   * @returns {string}\n   */\n  toHsv(): string {\n    const color = this.getColorAs('hsv');\n    const [h, s, v] = color.values.map(x => decimal(x, 2));\n    return color.alpha === 1\n      ? `hsv(${h}, ${s}%, ${v}%)`\n      : `hsva(${h}, ${s}%, ${v}%, ${color.alpha})`;\n  }\n\n  /**\n   * Represents color as CMYK notation. e.g. 'cmyk(0%, 0%, 0%, 0%)'\n   * @see https://www.w3.org/TR/css-color-4/#cmyk-colors\n   * @returns {string}\n   */\n  toCmyk(): string {\n    const color = this.getColorAs('cmyk');\n    const [c, m, y, k] = color.values.map(x => decimal(x, 2));\n    const a = color.alpha === 1 ? '' : `, ${color.alpha}`;\n    return `cmyk(${c}%, ${m}%, ${y}%, ${k}%${a})`;\n  }\n\n  protected convertFromRgb([r, g, b]: number[], model: AcceptedModel): number[] {\n    switch (model) {\n      case 'rgb': return [r, g, b];\n      case 'hwb': return Converter.rgbToHwb(r, g, b);\n      case 'hsl': return Converter.rgbToHsl(r, g, b);\n      case 'hsv': return Converter.rgbToHsv(r, g, b);\n      case 'cmyk': return Converter.rgbToCmyk(r, g, b);\n    }\n  }\n\n  protected convertFromHwb([h, w, b]: number[], model: AcceptedModel): number[] {\n    const [red, green, blue] = Converter.hwbToRgb(h, w, b);\n    switch (model) {\n      case 'rgb': return [red, green, blue];\n      case 'hwb': return [h, w, b];\n      case 'hsl': return Converter.rgbToHsl(red, green, blue);\n      case 'hsv': return Converter.hwbToHsv(h, w, b);\n      case 'cmyk': return Converter.rgbToCmyk(red, green, blue);\n    }\n  }\n\n  protected convertFromHsl([h, s, l]: number[], model: AcceptedModel): number[] {\n    const [red, green, blue] = Converter.hslToRgb(h, s, l);\n    switch (model) {\n      case 'rgb': return [red, green, blue];\n      case 'hwb': return Converter.rgbToHwb(red, green, blue);\n      case 'hsl': return [h, s, l];\n      case 'hsv': return Converter.rgbToHsv(red, green, blue);\n      case 'cmyk': return Converter.rgbToCmyk(red, green, blue);\n    }\n  }\n\n  protected convertFromHsv([h, s, v]: number[], model: AcceptedModel): number[] {\n    const [red, green, blue] = Converter.hsvToRgb(h, s, v);\n    switch (model) {\n      case 'rgb': return [red, green, blue];\n      case 'hwb': return Converter.hsvToHwb(h, s, v);\n      case 'hsl': return Converter.rgbToHsl(red, green, blue);\n      case 'hsv': return [h, s, v];\n      case 'cmyk': return Converter.rgbToCmyk(red, green, blue);\n    }\n  }\n\n  protected convertFromCmyk([c, m, y, k]: number[], model: AcceptedModel): number[] {\n    const [red, green, blue] = Converter.cmykToRgb(c, m, y, k);\n    switch (model) {\n      case 'rgb': return [red, green, blue];\n      case 'hwb': return Converter.rgbToHwb(red, green, blue);\n      case 'hsl': return Converter.rgbToHsl(red, green, blue);\n      case 'hsv': return Converter.rgbToHsv(red, green, blue);\n      case 'cmyk': return [c, m, y, k];\n    }\n  }\n}\n\nexport default ColorFormatter;\n","import * as ColorName from 'color-name';\n\ninterface ColorNames {\n  [index: string]: [number, number, number];\n}\n\nexport default ColorName as ColorNames;\n","import { Color } from './color';\nimport { resolveHwb } from './color-converter';\nimport Names from './color-names';\nimport { clamp, degree, resolveAlpha } from './util/util';\n\nexport default function inputParser(input: string): Color|null {\n  if (input in Names) {\n    // Named colors.\n    return {\n      model: 'rgb',\n      values: Names[input],\n      alpha: 1,\n    };\n  } else if (input === 'transparent') {\n    // 'transparent'.\n    return {\n      model: 'rgb',\n      values: [0, 0, 0],\n      alpha: 0,\n    };\n  } else {\n    // parse string.\n    const prefix = input.substr(0, 3).toLowerCase();\n    switch (prefix) {\n      case 'hwb': return parseHwb(input);\n      case 'hsl': return parseHsl(input);\n      case 'hsv': return parseHsv(input);\n      case 'cmy': return parseCmyk(input);\n      default: return parseRgb(input);\n    }\n  }\n}\n\nfunction parseRgb(input: string): Color|null {\n  const hex = /^#?([a-f0-9]{6})([a-f0-9]{2})?$/i;\n  const shortHex = /^#?([a-f0-9]{3})([a-f0-9]{1})?$/i;\n  const rgba = /^rgba?\\s*\\(\\s*([+-]?\\d+)\\s*,\\s*([+-]?\\d+)\\s*,\\s*([+-]?\\d+)\\s*(?:,\\s*([+-]?[\\d.]+)\\s*)?\\)$/;\n  // tslint:disable-next-line:max-line-length\n  const percent = /^rgba?\\s*\\(\\s*([+-]?[\\d.]+)%\\s*,\\s*([+-]?[\\d.]+)%\\s*,\\s*([+-]?[\\d.]+)%\\s*(?:,\\s*([+-]?[\\d.]+)\\s*)?\\)$/;\n  const hexToAlpha = (num: string) => Math.round((parseInt(num, 16) / 255) * 100) / 100;\n  let values: number[];\n  let alpha: number;\n\n  if (hex.test(input)) {\n    const [, h, a] = input.match(hex);\n    values = h.match(/.{2}/g).map(x => parseInt(x, 16));\n    alpha = a ? hexToAlpha(a) : 1;\n  } else if (shortHex.test(input)) {\n    const [, h, a] = input.match(shortHex);\n    values = h.match(/.{1}/g).map(x => parseInt(x + x, 16));\n    alpha = a ? hexToAlpha(a) : 1;\n  } else if (rgba.test(input)) {\n    const [, r, g, b, a] = input.match(rgba);\n    values = [r, g, b].map(x => parseInt(x, 0));\n    alpha = resolveAlpha(a);\n  } else if (percent.test(input)) {\n    const [, r, g, b, a] = input.match(percent);\n    values = [r, g, b].map(x => Math.round(parseFloat(x) * 2.55));\n    alpha = resolveAlpha(a);\n  } else {\n    return null;\n  }\n  return {\n    model: 'rgb',\n    values: values.map(x => clamp(x, 0, 255)),\n    alpha: clamp(alpha, 0, 1),\n  };\n}\n\nfunction parseHsl(input: string): Color|null {\n  // tslint:disable-next-line:max-line-length\n  const hsl = /^hsla?\\s*\\(\\s*([+-]?\\d*[.]?\\d+)(?:deg)?\\s*,\\s*([+-]?[\\d.]+)%\\s*,\\s*([+-]?[\\d.]+)%\\s*(?:,\\s*([+-]?[\\d.]+)\\s*)?\\)$/i;\n\n  if (hsl.test(input)) {\n    const [, h, s, l, a] = input.match(hsl);\n    return {\n      model: 'hsl',\n      values: [\n        degree(h),\n        clamp(parseFloat(s), 0, 100),\n        clamp(parseFloat(l), 0, 100),\n      ],\n      alpha: resolveAlpha(a),\n    };\n  } else {\n    return null;\n  }\n}\n\nfunction parseHwb(input: string): Color|null {\n  // tslint:disable-next-line:max-line-length\n  const hwb = /^hwba?\\s*\\(\\s*([+-]?\\d*[.]?\\d+)(?:deg)?\\s*,\\s*([+-]?[\\d.]+)%\\s*,\\s*([+-]?[\\d.]+)%\\s*(?:,\\s*([+-]?[\\d.]+)\\s*)?\\)$/i;\n\n  if (hwb.test(input)) {\n    const [, h, w, b, a] = input.match(hwb);\n    return {\n      model: 'hwb',\n      values: resolveHwb(\n        degree(h),\n        clamp(parseFloat(w), 0, 100),\n        clamp(parseFloat(b), 0, 100),\n      ),\n      alpha: resolveAlpha(a),\n    };\n  } else {\n    return null;\n  }\n}\n\nfunction parseHsv(input: string): Color|null {\n  // tslint:disable-next-line:max-line-length\n  const hsv = /^hsva?\\s*\\(\\s*([+-]?\\d*[.]?\\d+)(?:deg)?\\s*,\\s*([+-]?[\\d.]+)%\\s*,\\s*([+-]?[\\d.]+)%\\s*(?:,\\s*([+-]?[\\d.]+)\\s*)?\\)$/i;\n\n  if (hsv.test(input)) {\n    const [, h, s, v, a] = input.match(hsv);\n    return {\n      model: 'hsv',\n      values: [\n        degree(h),\n        clamp(parseFloat(s), 0, 100),\n        clamp(parseFloat(v), 0, 100),\n      ],\n      alpha: resolveAlpha(a),\n    };\n  } else {\n    return null;\n  }\n}\n\nfunction parseCmyk(input: string): Color|null {\n  // tslint:disable-next-line:max-line-length\n  const cmyk = /^cmyk\\s*\\(\\s*([+-]?[\\d.]+)%\\s*,\\s*([+-]?[\\d.]+)%\\s*,\\s*([+-]?[\\d.]+)%\\s*,\\s*([+-]?[\\d.]+)%\\s*(?:,\\s*([+-]?[\\d.]+)\\s*)?\\)$/i;\n\n  if (cmyk.test(input)) {\n    const [, c, m, y, k, a] = input.match(cmyk);\n    return {\n      model: 'cmyk',\n      values: [\n        clamp(parseFloat(c), 0, 100),\n        clamp(parseFloat(m), 0, 100),\n        clamp(parseFloat(y), 0, 100),\n        clamp(parseFloat(k), 0, 100),\n      ],\n      alpha: resolveAlpha(a),\n    };\n  } else {\n    return null;\n  }\n}\n","import {\n  AcceptedModel,\n  Color,\n  ColorModifiable,\n  ColorStateAccessible,\n  RandomArguments,\n} from './color';\nimport { resolveHwb } from './color-converter';\nimport ColorFormatter from './color-formatter';\nimport parser from './input-parser';\nimport {\n  clamp,\n  degree,\n  getRandom,\n} from './util/util';\n\nexport * from './color';\n\nexport { ColorFormatter };\n\ntype manipulateFn = (...args: number[]) => number[];\n\nexport class MooColor extends ColorFormatter implements ColorModifiable<MooColor>, ColorStateAccessible {\n\n  static mix(color1: MooColor|string|Color, color2: MooColor|string|Color, percentOf1: number = 50): MooColor {\n    const c1 = (color1 instanceof MooColor) ? color1 : new MooColor(color1);\n    const c2 = (color2 instanceof MooColor) ? color2 : new MooColor(color2);\n    return c2.mix(c1, percentOf1);\n  }\n\n  /**\n   * Create random color as HWB color model.\n   *\n   * @static\n   * @param {RandomArguments} [{hue, white, black}={}]\n   * @returns {MooColor}\n   * @memberof MooColor\n   */\n  static random({hue, white, black}: RandomArguments = {}): MooColor {\n    [hue, white, black] = [hue, white, black].map((x, i) => {\n      if (typeof x === 'number') {\n        return x;\n      } else if (Array.isArray(x)) {\n        const precision = i === 0 ? 0 : 2;\n        return getRandom(Math.min(...x), Math.max(...x), precision);\n      } else {\n        return i === 0 ? getRandom(0, 360) : getRandom(0, 100, 2);\n      }\n    });\n    return new MooColor({\n      model: 'hwb',\n      values: resolveHwb(degree(hue), clamp(white, 0, 100), clamp(black, 0, 100)),\n      alpha: 1,\n    });\n  }\n\n  /**\n   * Creates an instance of MooColor.\n   * @param {(string|Color)} [color] color value. e.g. '#ff0000' 'rgba(255, 0, 0, .5)' 'hsl(120, 50%, 100%)'\n   * @memberof MooColor\n   */\n  constructor(color?: string|Color) {\n    super();\n    if (typeof color === 'object' && color !== null) {\n      this.setColor(color as Color);\n    } else if (typeof color === 'string' || typeof color === 'undefined') {\n      color = color ? color : '#000';\n      this.setColorByParser(color as string);\n    }\n  }\n\n  setColorByParser(str: string): this {\n    const color: Color = parser(str);\n    if (!color) {\n      throw new Error('parsing error!');\n    }\n    return this.setColor(color);\n  }\n\n  clone(): MooColor {\n    return new MooColor(this.color);\n  }\n\n  /**\n   * Returns color brightness from 0 to 255. (It based RGB)\n   * @see https://www.w3.org/TR/AERT/#color-contrast\n   * @readonly\n   * @type {number}\n   */\n  get brightness(): number {\n    const [r, g, b] = this.getColorAs('rgb').values;\n    return ((r * 299) + (g * 587) + (b * 114)) / 1000;\n  }\n\n  /**\n   * Returns whether color is light or not.\n   * @readonly\n   * @type {boolean}\n   */\n  get isLight(): boolean {\n    return this.brightness >= 128;\n  }\n\n  /**\n   * Returns whether color is dark or not.\n   * @readonly\n   * @type {boolean}\n   */\n  get isDark(): boolean {\n    return this.brightness < 128;\n  }\n\n  /**\n   * Returns luminance value of the color. value from 0 to 1.\n   * @see https://www.w3.org/TR/2008/REC-WCAG20-20081211/#relativeluminancedef\n   * @readonly\n   * @type {number}\n   */\n  get luminance(): number {\n    const [r, g, b] = this.getColorAs('rgb').values.map(x => x / 255);\n    return 0.2126 * r + 0.7152 * g + 0.0722 * b;\n  }\n\n  /**\n   * Returns contrast ratio with other color. range from 0 to 21.\n   * @see https://www.w3.org/TR/2008/REC-WCAG20-20081211/#relativeluminancedef\n   * @param {MooColor} color\n   * @returns {number} 0-21\n   */\n  contrastRatioWith(color: MooColor): number {\n    const max = Math.max(this.luminance, color.luminance);\n    const min = Math.min(this.luminance, color.luminance);\n    return (max + 0.05) / (min + 0.05);\n  }\n\n  /**\n   * Return true if contrast ratio >= 4.5\n   * @see https://www.w3.org/WAI/WCAG20/quickref/#qr-visual-audio-contrast-contrast\n   * @param {MooColor} color\n   * @returns {boolean}\n   */\n  isContrastEnough(color: MooColor): boolean {\n    return this.contrastRatioWith(color) >= 4.5;\n  }\n\n  /**\n   * Increase lightness.\n   * @param {number} amount The amount from 0 to 100.\n   * @returns {this}\n   */\n  lighten(amount: number): this {\n    return this.manipulate('hsl', (h, s, l) => {\n      l = clamp(l + amount, 0, 100);\n      return [h, s, l];\n    });\n  }\n\n  /**\n   * Decrease lightness.\n   * @param {number} amount The amount from 0 to 100.\n   * @returns {this}\n   */\n  darken(amount: number): this {\n    return this.manipulate('hsl', (h, s, l) => {\n      l = clamp(l - amount, 0, 100);\n      return [h, s, l];\n    });\n  }\n\n  /**\n   * Increase saturation.\n   * @param {number} amount The amount from 0 to 100.\n   * @returns {this}\n   */\n  saturate(amount: number): this {\n    return this.manipulate('hsl', (h, s, l) => {\n      s = clamp(s + amount, 0, 100);\n      return [h, s, l];\n    });\n  }\n\n  /**\n   * Decrease saturation.\n   * @param {number} amount The amount from 0 to 100.\n   * @returns {this}\n   */\n  desaturate(amount: number): this {\n    return this.manipulate('hsl', (h, s, l) => {\n      s = clamp(s - amount, 0, 100);\n      return [h, s, l];\n    });\n  }\n\n  /**\n   * Sets saturation value to 0.\n   * @returns {this}\n   */\n  grayscal